import os
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import ClientError


def resolve_bedrock_model_id(model_name_or_id: str) -> str:
    """
    Resolve a provider-specific Amazon Bedrock model identifier before invocation.

    Accepts either a concrete Bedrock model ID or a friendly alias.
    """
    alias_map = {
        "claude-3-5-sonnet": "anthropic.claude-3-5-sonnet-20240620-v1:0",
        "claude-3-sonnet": "anthropic.claude-3-sonnet-20240229-v1:0",
        "claude-3-haiku": "anthropic.claude-3-haiku-20240307-v1:0",
        "llama-3-1-70b": "meta.llama3-1-70b-instruct-v1:0",
        "llama-3-1-8b": "meta.llama3-1-8b-instruct-v1:0",
        "mistral-large": "mistral.mistral-large-2402-v1:0",
        "titan-text-express": "amazon.titan-text-express-v1",
    }
    normalized = model_name_or_id.strip()
    return alias_map.get(normalized.lower(), normalized)


def invoke_bedrock_text(
    prompt: str,
    model_name_or_id: str = "anthropic.claude-3-5-sonnet-20240620-v1:0",
    region_name: Optional[str] = None,
    max_tokens: int = 256,
    temperature: float = 0.7,
) -> Dict[str, Any]:
    """
    Resolve a Bedrock model/deployment resource and invoke it via boto3.
    """
    resolved_model_id = resolve_bedrock_model_id(model_name_or_id)
    bedrock = boto3.client("bedrock-runtime", region_name=region_name or os.getenv("AWS_REGION"))

    body = {
        "anthropic_version": "bedrock-2023-05-31",
        "max_tokens": max_tokens,
        "temperature": temperature,
        "messages": [
            {"role": "user", "content": [{"type": "text", "text": prompt}]}
        ],
    }

    try:
        response = bedrock.invoke_model(
            modelId=resolved_model_id,
            contentType="application/json",
            accept="application/json",
            body=__import__("json").dumps(body),
        )
        payload = __import__("json").loads(response["body"].read())
        text_parts = []
        for item in payload.get("content", []):
            if item.get("type") == "text":
                text_parts.append(item.get("text", ""))
        return {
            "provider": "amazon_bedrock",
            "model_id": resolved_model_id,
            "output_text": "".join(text_parts),
            "raw": payload,
        }
    except ClientError as e:
        raise RuntimeError(f"Bedrock invocation failed for model '{resolved_model_id}': {e}") from e


def converse_bedrock(
    system_prompt: str,
    user_prompt: str,
    model_name_or_id: str = "anthropic.claude-3-5-sonnet-20240620-v1:0",
    region_name: Optional[str] = None,
    max_tokens: int = 256,
    temperature: float = 0.7,
) -> Dict[str, Any]:
    """
    Resolve a Bedrock model/deployment resource and invoke it using converse().
    """
    resolved_model_id = resolve_bedrock_model_id(model_name_or_id)
    bedrock = boto3.client("bedrock-runtime", region_name=region_name or os.getenv("AWS_REGION"))

    try:
        response = bedrock.converse(
            modelId=resolved_model_id,
            system=[{"text": system_prompt}],
            messages=[
                {"role": "user", "content": [{"text": user_prompt}]}
            ],
            inferenceConfig={
                "maxTokens": max_tokens,
                "temperature": temperature,
            },
        )
        output_message = response.get("output", {}).get("message", {})
        text_parts = []
        for item in output_message.get("content", []):
            if "text" in item:
                text_parts.append(item["text"])
        return {
            "provider": "amazon_bedrock",
            "model_id": resolved_model_id,
            "output_text": "".join(text_parts),
            "raw": response,
        }
    except ClientError as e:
        raise RuntimeError(f"Bedrock converse failed for model '{resolved_model_id}': {e}") from e
